cal_plan_items.clinic_id) AS is_clinic_staff)","roles":["authenticated"],"tablename":"clinical_plan_items","permissive":"PERMISSIVE","policyname":"clinical_plan_items_staff_manage","schemaname":"public","with_check":"( SELECT private.is_clinic_staff(clinical_plan_items.clinic_id) AS is_clinic_staff)"},{"cmd":"SELECT","qual":"( SELECT private.can_access_patient(clinical_plans.clinic_id, clinical_plans.patient_id) AS can_access_patient)","roles":["authenticated"],"tablename":"clinical_plans","permissive":"PERMISSIVE","policyname":"clinical_plans_access","schemaname":"public","with_check":null},{"cmd":"ALL","qual":"( SELECT private.is_clinic_staff(clinical_plans.clinic_id) AS is_clinic_staff)","roles":["authenticated"],"tablename":"clinical_plans","permissive":"PERMISSIVE","policyname":"clinical_plans_staff_manage","schemaname":"public","with_check":"( SELECT private.is_clinic_staff(clinical_plans.clinic_id) AS is_clinic_staff)"},{"cmd":"SELECT","qual":"( SELECT private.can_access_patient(consent_requirements.clinic_id, consent_requirements.patient_id) AS can_access_patient)","roles":["authenticated"],"tablename":"consent_requirements","permissive":"PERMISSIVE","policyname":"consent_requirements_access","schemaname":"public","with_check":null},{"cmd":"ALL","qual":"( SELECT private.is_clinic_staff(consent_requirements.clinic_id) AS is_clinic_staff)","roles":["authenticated"],"tablename":"consent_requirements","permissive":"PERMISSIVE","policyname":"consent_requirements_staff_manage","schemaname":"public","with_check":"( SELECT private.is_clinic_staff(consent_requirements.clinic_id) AS is_clinic_staff)"},{"cmd":"ALL","qual":"( SELECT private.is_clinic_admin(document_templates.clinic_id) AS is_clinic_admin)","roles":["authenticated"],"tablename":"document_templates","permissive":"PERMISSIVE","policyname":"document_templates_admin_manage","schemaname":"public","with_check":"( SELECT private.is_clinic_admin(document_templates.clinic_id) AS is_clinic_admin)"},{"cmd":"SELECT","qual":"( SELECT private.is_clinic_staff(document_templates.clinic_id) AS is_clinic_staff)","roles":["authenticated"],"tablename":"document_templates","permissive":"PERMISSIVE","policyname":"document_templates_staff_select","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"( SELECT private.can_access_patient(patient_recalls.clinic_id, patient_recalls.patient_id) AS can_access_patient)","roles":["authenticated"],"tablename":"patient_recalls","permissive":"PERMISSIVE","policyname":"patient_recalls_access","schemaname":"public","with_check":null},{"cmd":"ALL","qual":"( SELECT private.is_clinic_staff(patient_recalls.clinic_id) AS is_clinic_staff)","roles":["authenticated"],"tablename":"patient_recalls","permissive":"PERMISSIVE","policyname":"patient_recalls_staff_manage","schemaname":"public","with_check":"( SELECT private.is_clinic_staff(patient_recalls.clinic_id) AS is_clinic_staff)"},{"cmd":"SELECT","qual":"( SELECT private.can_access_patient(patient_waitlist_requests.clinic_id, patient_waitlist_requests.patient_id) AS can_access_patient)","roles":["authenticated"],"tablename":"patient_waitlist_requests","permissive":"PERMISSIVE","policyname":"patient_waitlist_access","schemaname":"public","with_check":null},{"cmd":"INSERT","qual":null,"roles":["authenticated"],"tablename":"patient_waitlist_requests","permissive":"PERMISSIVE","policyname":"patient_waitlist_patient_insert","schemaname":"public","with_check":"(( SELECT private.is_patient_owner(patient_waitlist_requests.patient_id) AS is_patient_owner) AND (priority = 0) AND (status = ''ACTIVE''::text) AND (fulfilled_at IS NULL) AND (appointment_id IS NULL))"},{"cmd":"ALL","qual":"( SELECT private.is_clinic_staff(patient_waitlist_requests.clinic_id) AS is_clinic_staff)","roles":["authenticated"],"tablename":"patient_waitlist_requests","permissive":"PERMISSIVE","policyname":"patient_waitlist_staff_manage","schemaname":"public","with_check":"( SELECT private.is_clinic_staff(patient_waitlist_requests.clinic_id) AS is_clinic_staff)"},{"cmd":"ALL","qual":"( SELECT private.is_clinic_admin(payment_terminals.clinic_id) AS is_clinic_admin)","roles":["authenticated"],"tablename":"payment_terminals","permissive":"PERMISSIVE","policyname":"payment_terminals_admin_manage","schemaname":"public","with_check":"( SELECT private.is_clinic_admin(payment_terminals.clinic_id) AS is_clinic_admin)"},{"cmd":"SELECT","qual":"( SELECT private.is_clinic_staff(payment_terminals.clinic_id) AS is_clinic_staff)","roles":["authenticated"],"tablename":"payment_terminals","permissive":"PERMISSIVE","policyname":"payment_terminals_staff_select","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"( SELECT private.can_access_patient(periodontal_measurements.clinic_id, periodontal_measurements.patient_id) AS can_access_patient)","roles":["authenticated"],"tablename":"periodontal_measurements","permissive":"PERMISSIVE","policyname":"periodontal_access","schemaname":"public","with_check":null},{"cmd":"ALL","qual":"( SELECT private.is_clinic_staff(periodontal_measurements.clinic_id) AS is_clinic_staff)","roles":["authenticated"],"tablename":"periodontal_measurements","permissive":"PERMISSIVE","policyname":"periodontal_staff_manage","schemaname":"public","with_check":"( SELECT private.is_clinic_staff(periodontal_measurements.clinic_id) AS is_clinic_staff)"},{"cmd":"ALL","qual":"( SELECT private.is_clinic_admin(sites.clinic_id) AS is_clinic_admin)","roles":["authenticated"],"tablename":"sites","permissive":"PERMISSIVE","policyname":"sites_admin_manage","schemaname":"public","with_check":"( SELECT private.is_clinic_admin(sites.clinic_id) AS is_clinic_admin)"},{"cmd":"SELECT","qual":"( SELECT private.is_clinic_staff(sites.clinic_id) AS is_clinic_staff)","roles":["authenticated"],"tablename":"sites","permissive":"PERMISSIVE","policyname":"sites_staff_select","schemaname":"public","with_check":null},{"cmd":"ALL","qual":"( SELECT private.is_clinic_admin(staff_absences.clinic_id) AS is_clinic_admin)","roles":["authenticated"],"tablename":"staff_absences","permissive":"PERMISSIVE","policyname":"staff_absences_admin_manage","schemaname":"public","with_check":"( SELECT private.is_clinic_admin(staff_absences.clinic_id) AS is_clinic_admin)"},{"cmd":"SELECT","qual":"( SELECT private.is_clinic_staff(staff_absences.clinic_id) AS is_clinic_staff)","roles":["authenticated"],"tablename":"staff_absences","permissive":"PERMISSIVE","policyname":"staff_absences_staff_select","schemaname":"public","with_check":null},{"cmd":"ALL","qual":"( SELECT private.is_clinic_admin(staff_members.clinic_id) AS is_clinic_admin)","roles":["authenticated"],"tablename":"staff_members","permissive":"PERMISSIVE","policyname":"staff_members_admin_manage","schemaname":"public","with_check":"( SELECT private.is_clinic_admin(staff_members.clinic_id) AS is_clinic_admin)"},{"cmd":"SELECT","qual":"( SELECT private.is_clinic_staff(staff_members.clinic_id) AS is_clinic_staff)","roles":["authenticated"],"tablename":"staff_members","permissive":"PERMISSIVE","policyname":"staff_members_staff_select","schemaname":"public","with_check":null},{"cmd":"ALL","qual":"( SELECT private.is_clinic_admin(staff_schedules.clinic_id) AS is_clinic_admin)","roles":["authenticated"],"tablename":"staff_schedules","permissive":"PERMISSIVE","policyname":"staff_schedules_admin_manage","schemaname":"public","with_check":"( SELECT private.is_clinic_admin(staff_schedules.clinic_id) AS is_clinic_admin)"},{"cmd":"SELECT","qual":"( SELECT private.is_clinic_staff(staff_schedules.clinic_id) AS is_clinic_staff)","roles":["authenticated"],"tablename":"staff_schedules","permissive":"PERMISSIVE","policyname":"staff_schedules_staff_select","schemaname":"public","with_check":null},{"cmd":"ALL","qual":"( SELECT private.is_clinic_admin(staff_settings.clinic_id) AS is_clinic_admin)","roles":["authenticated"],"tablename":"staff_settings","permissive":"PERMISSIVE","policyname":"staff_settings_admin_manage","schemaname":"public","with_check":"( SELECT private.is_clinic_admin(staff_settings.clinic_id) AS is_clinic_admin)"},{"cmd":"SELECT","qual":"( SELECT private.is_clinic_staff(staff_settings.clinic_id) AS is_clinic_staff)","roles":["authenticated"],"tablename":"staff_settings","permissive":"PERMISSIVE","policyname":"staff_settings_staff_select","schemaname":"public","with_check":null}]'::jsonb);
create temp table scope_assertions(table_name text, expected_digest text);
grant select,insert,delete on scope_assertions to authenticated;
do $$ declare member public.clinic_members%rowtype; begin
  select * into member from public.clinic_members where active and role='ADMIN' limit 1;
  if member.id is null then raise exception 'Fixture requires an active admin'; end if;
  perform set_config('app.test_profile',member.profile_id::text,true);
  perform set_config('app.test_clinic',member.clinic_id::text,true);
end $$;
do $test$
declare actor text; target text; predicate text; expected_digest text; actual_digest text;
  operation text; clause text; expected_predicate text; actual_predicate text; differs boolean;
begin
  foreach actor in array array['ADMIN','RECEPTION','DENTIST','ASSISTANT','PATIENT','OUTSIDER'] loop
    perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('app.test_profile'),'role','authenticated')::text,true);
    if actor in ('ADMIN','RECEPTION','DENTIST','ASSISTANT') then
      update public.clinic_members set role=actor,active=true where profile_id=current_setting('app.test_profile')::uuid;
    elsif actor='PATIENT' then
      update public.clinic_members set active=false where profile_id=current_setting('app.test_profile')::uuid;
      insert into public.patient_accounts(clinic_id,patient_id,profile_id)
        select clinic_id,id,current_setting('app.test_profile')::uuid from public.patients
        where clinic_id=current_setting('app.test_clinic')::uuid order by id limit 1
        on conflict do nothing;
    else
      perform set_config('request.jwt.claims',jsonb_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);
    end if;
    for target in select distinct tablename from original_policies loop
      select string_agg('('||coalesce(qual,'true')||')',' OR ') into predicate
        from original_policies where tablename=target and cmd in ('SELECT','ALL');
      execute format($query$select md5(coalesce(string_agg(to_jsonb(%1$I)::text,',' order by to_jsonb(%1$I)::text),'')) from public.%1$I where %2$s$query$,target,predicate) into expected_digest;
      perform set_config('role','authenticated',true);
      execute format($query$select md5(coalesce(string_agg(to_jsonb(%1$I)::text,',' order by to_jsonb(%1$I)::text),'')) from public.%1$I$query$,target) into actual_digest;
      perform set_config('role','postgres',true);
      if expected_digest is distinct from actual_digest then
        raise exception 'Access regression for % on %',actor,target;
      end if;
      foreach operation in array array['INSERT','UPDATE','DELETE'] loop
        foreach clause in array array['USING','CHECK'] loop
          if (operation='INSERT' and clause='USING') or (operation='DELETE' and clause='CHECK') then continue; end if;
          select string_agg('('||case when clause='CHECK' then coalesce(with_check,qual,'true') else coalesce(qual,'true') end||')',' OR ')
            into expected_predicate from original_policies where tablename=target and cmd in (operation,'ALL');
          select string_agg('('||case when clause='CHECK' then coalesce(with_check,qual,'true') else coalesce(qual,'true') end||')',' OR ')
            into actual_predicate from pg_policies where schemaname='public' and tablename=target and cmd=operation;
          if actual_predicate is null then raise exception 'Missing % policy for %',operation,target; end if;
          execute format($query$select exists(select 1 from public.%1$I where coalesce((%2$s),false) is distinct from coalesce((%3$s),false))$query$,
            target,expected_predicate,actual_predicate) into differs;
          if differs then raise exception '% % regression for % on %',operation,clause,actor,target; end if;
        end loop;
      end loop;
    end loop;
  end loop;
end $test$;
rollback;
